const wholesalerQuestionPrompts = [
 {category:'Campaigns',title:'Write an advisor education email series',time:'5 min',copy:'Using approved public educational materials on [topic], create three short advisor emails, each with one practical takeaway, one balanced risk reminder, and a neutral meeting invitation. Identify claims needing compliance approval and avoid invented performance figures.'},
 {category:'Meetings',title:'AI prompts for advisor meeting prep',time:'4 min',copy:'Create a fifteen-minute introductory advisor meeting agenda using only public information and hypothetical interests. Include a concise opening, five discovery questions, a useful practice-management idea, and a follow-up plan. Do not invent holdings or advisor preferences.'},
 {category:'Operations',title:'How to use AI in a wholesaler sales workflow',time:'5 min',copy:'Design a weekly wholesaler workflow for call preparation, follow-up drafting, content approval, and territory review. Include suggested time blocks, inputs restricted to approved sanitized data, and a manual review step before anything enters CRM.'},
 {category:'Territory',title:'Plan more productive advisor meetings',time:'5 min',copy:'Using hypothetical advisor segments and approved public office locations, build a sample week of outreach and meetings. Rank priorities using explicit criteria, explain uncertainty, and avoid fabricated travel times, sales figures or buying intent.'},
];
const questionTopics={advisor:[
 ['How can AI help financial advisors get started?','Begin with one repeatable task, such as a meeting agenda or a draft follow-up. Use hypothetical details, review the output, and follow your firm’s AI policy.','Operations','get started'],
 ['How can advisors use AI for client emails?','AI can draft plain-English educational or follow-up emails from approved non-sensitive inputs. Confirm every fact and complete required review before sending.','Communication','client emails'],
 ['What are useful AI prompts for meeting preparation?','Agenda building, discovery questions, recap checklists and drafting next steps are practical starting points. Do not paste unapproved private client notes.','Meetings','meeting preparation'],
 ['Can AI help with referrals and prospecting?','AI can suggest outreach themes, neutral introductions and follow-up plans. Firm marketing rules and anti-testimonial/incentive restrictions still apply.','Growth','referral'],
 ['Can AI explain market volatility to clients?','It can simplify approved public commentary, but should not make personalized recommendations, promise outcomes or invent market statistics.','Communication','market volatility'],
 ['Is ChatGPT compliant for financial advisors?','Compliance depends on the specific deployment, data, use case and firm requirements. A general AI account is not automatically approved for client information or recommendations.','Operations','AI practice']
],wholesaler:[
 ['How can wholesalers use AI to prepare for advisor meetings?','Use public facts and approved notes to draft agendas, discovery questions and follow-up plans; verify all product claims.','Meetings','advisor meeting prep'],
 ['Can AI help wholesalers prospect for advisors?','It can organize firm-approved territory segments and plan outreach; it must not invent advisor assets, preferences or likelihood to buy.','Territory','advisor meetings'],
 ['How do wholesalers use AI to write educational emails?','Start with approved product or market material; ask for a short balanced draft and route it through the firm’s established approval process.','Campaigns','advisor education email'],
 ['What are practical AI workflows for wholesalers?','Meeting prep, approved content simplification, CRM recap drafts and weekly call plans are straightforward places to start.','Operations','sales workflow']
]};

export default function App(){
 const [role,setRole] = useState(()=>{try{return localStorage.getItem('aipb_role')==='wholesaler'?'wholesaler':'advisor'}catch{return 'advisor'}});
 const prompts = role==='advisor' ? [...advisorPrompts,...advisorExtras,...advisorDiscoveryPrompts,...advisorQuestionPrompts] : [...wholesalerPrompts,...wholesalerDiscoveryPrompts,...wholesalerQuestionPrompts];
 const workflow = role==='advisor' ? advisorWorkflow : wholesalerWorkflow;
 const categories = role==='advisor' ? ['All','Meetings','Communication','Growth','Operations'] : ['All','Territory','Meetings','Products','Campaigns','Operations'];
 const [category,setCategory] = useState('All');
 const [query,setQuery] = useState('');
 const [copied,setCopied] = useState(-1);
 const [expanded,setExpanded] = useState(0);
 const selected=useMemo(()=>prompts.map((p,index)=>({...p,index})).filter(p=>(category==='All'||p.category===category) && (p.title+' '+p.copy).toLowerCase().includes(query.toLowerCase())),[category,query,role]);
 const changeRole=(r)=>{try{localStorage.setItem('aipb_role',r)}catch{} setRole(r);setCategory('All');setQuery('');setCopied(-1);};
 const choose=(c,term='')=>{setQuery(term);setCategory(c); document.querySelector('#prompt-library')?.scrollIntoView({behavior:'smooth'});};
 async function copyPrompt(p){ try{ await navigator.clipboard.writeText(p.copy);setCopied(p.index);window.setTimeout(()=>setCopied(-1),2200);}catch{ window.prompt('Copy this prompt:',p.copy); } }
 return <div className="site">
  <header className="nav"><div className="shell nav-inner"><a className="brand" href="#top" aria-label="Advisor AI Blueprint home"><span className="brand-mark">A<span>✦</span></span><span><strong>AI Practice Blueprint</strong><small>Simple AI. Stronger relationships.</small></span></a><div className="role-switch" aria-label="Choose your role"><button aria-pressed={role==='advisor'} className={role==='advisor'?'current':''} onClick={()=>changeRole('advisor')}>Advisor</button><button aria-pressed={role==='wholesaler'} className={role==='wholesaler'?'current':''} onClick={()=>changeRole('wholesaler')}>Wholesaler</button></div><nav className="nav-links" aria-label="Main navigation"><a href="#start-here">Start here</a><a href="#how">How it works</a><a href="#prompt-library">Prompt library</a><a href="#resources">Free guides</a><a href="#safety">AI guardrails</a></nav><a className="nav-cta" href="#prompt-library">Try a prompt <span aria-hidden="true">↗</span></a></div></header>
  <main id="top">
   <section className="hero"><div className="shell hero-grid"><div className="hero-copy"><div className="eyebrow"><span className="green-dot"/> PRACTICAL AI FOR {role==='advisor'?'FINANCIAL ADVISORS':'ETF & ASSET MANAGEMENT WHOLESALERS'}</div><h1>{role==='advisor'?<>Less busywork.<br/><em>More time</em> for clients.</>:<>Less admin.<br/><em>More time</em> with advisors.</>}</h1><p className="hero-intro">{role==='advisor'?'You don’t need to become a tech expert to benefit from AI. Start with easy, real-world workflows that help your practice prepare, communicate, follow up, and stay organized.':'Make every territory day count. Use straightforward AI workflows to prioritize advisors, prepare for meetings, simplify product stories, and follow up consistently.'}</p><div className="hero-actions"><a className="btn btn-primary" href="#start-here">Find my AI workflow <span>→</span></a><a className="btn btn-secondary" href={role==='advisor'?'/guides/advisor-ai-one-page.pdf':'/guides/wholesaler-ai-one-page.pdf'} download>Download 1-page guide <span>↓</span></a></div><div className="hero-proof"><span>✓ No technical experience required</span><span>✓ Copy-and-paste examples</span><span>✓ Compliance-conscious approach</span></div></div><div className="hero-visual"><div className="visual-top"><span className="visual-label">YOUR PRACTICE, SIMPLIFIED</span><span className="visual-pulse">● WORKFLOW</span></div><div className="visual-title">From scattered tasks to a clear next step.</div><div className="flow-line"><div className="flow-icon">01</div><div><strong>Start with a task</strong><small>{role==='advisor'?'“I need to prep for tomorrow’s client reviews.”':'“I need to prep for tomorrow’s advisor meetings.”'}</small></div><span className="flow-check">✓</span></div><div className="flow-connector"/><div className="flow-line"><div className="flow-icon">02</div><div><strong>Use a simple prompt</strong><small>Copy, customize, and add safe context.</small></div><span className="flow-check">✓</span></div><div className="flow-connector"/><div className="flow-line"><div className="flow-icon">03</div><div><strong>Review your draft</strong><small>Check accuracy, privacy, and firm policies.</small></div><span className="flow-check">✓</span></div><div className="visual-bottom">AI does the first draft. <strong>You stay in control.</strong></div></div></div></section>
   <section className="metric-strip"><div className="shell metric-inner"><div><b>01</b><span>Choose one task</span></div><div><b>02</b><span>Copy a ready-made prompt</span></div><div><b>03</b><span>Review and refine</span></div><div><b>04</b><span>Repeat what works</span></div></div></section>
   <section id="start-here" className="section discovery-section"><div className="shell"><div className="section-heading"><div><div className="kicker">START WITH YOUR PROBLEM</div><h2>What would you like to improve today?</h2></div><p>Skip the tech jargon. Pick a common challenge and go directly to a prompt that can help.</p></div><div className="discovery-grid">{discoveryTopics[role].map(t=><button className="discovery-option" key={t.label} onClick={()=>choose(t.category,t.term)}><span>{t.label}</span><span aria-hidden="true">↗</span></button>)}</div><p className="discovery-note">Educational examples only. Use approved tools and non-sensitive inputs.</p></div></section>
   <section id="popular-questions" className="section questions-section"><div className="shell"><div className="section-heading"><div><div className="kicker">COMMON QUESTIONS</div><h2>Practical answers to everyday AI questions.</h2></div><p>Choose a topic to find an actionable example in the prompt library. Start with a simple task, not complicated technology.</p></div><div className="question-grid">{questionTopics[role].map(([q,a,c,term])=><article className="question-card" key={q}><h3>{q}</h3><p>{a}</p><button onClick={()=>choose(c,term)}>Find a related prompt <span aria-hidden="true">↗</span></button></article>)}</div></div></section>
   <section id="how" className="section"><div className="shell"><div className="section-heading"><div><div className="kicker">THE BLUEPRINT</div><h2>Six simple ways to put AI to work.</h2></div><p>Focus on the everyday work that takes time away from relationships. Start small. Keep what works.</p></div><div className="workflow-grid">{workflow.map(w=><button key={w.num} className="workflow-card" onClick={()=>choose(w.category)}><span className="workflow-num">{w.num} / {w.label}</span><h3>{w.title}</h3><p>{w.detail}</p><span className="mini-link">See related prompts <span>↗</span></span></button>)}</div></div></section>
   <section className="dark-feature"><div className="shell feature-inner"><div><div className="kicker light">THE BIG IDEA</div><h2>AI shouldn’t complicate your practice.<br/><em>It should simplify it.</em></h2></div><p>Think of AI as an assistant for the first draft — not an investment committee, compliance officer, or replacement for your expertise.</p></div></section>
   <section id="prompt-library" className="section library-section"><div className="shell"><div className="section-heading"><div><div className="kicker">FREE {role==='advisor'?'ADVISOR':'WHOLESALER'} PROMPT LIBRARY · {prompts.length} PROMPTS</div><h2>Find a prompt. Copy it. Put it to work.</h2></div><p>{role==='advisor'?'Real-world advisor prompts for client service and practice growth. Adapt them to your firm-approved tools.':'Territory, meeting, product, campaign, and operations prompts for wholesalers. Use approved information and review externally facing drafts.'}</p></div><div className="prompt-toolbar"><div className="chip-list" aria-label="Filter prompts">{categories.map(c=><button className={'chip '+(category===c?'active':'')} aria-pressed={category===c} key={c} onClick={()=>setCategory(c)}>{c}</button>)}</div><label className="search-wrap"><span aria-hidden="true">⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search prompts..." aria-label="Search prompts"/></label></div><div className="prompt-grid">{selected.map(p=><article className="prompt-card" key={p.index}><div className="prompt-meta"><span>{p.category}</span><span>~{p.time} setup</span></div><h3>{p.title}</h3><p className="prompt-preview">{p.copy}</p><button className="copy-btn" onClick={()=>copyPrompt(p)}>{copied===p.index?'✓ Copied':'▣ Copy prompt'} <span>↗</span></button></article>)}</div>{selected.length===0&&<div className="empty">No prompts match that search. Try a different term or choose “All.”</div>}<p className="privacy-note"><strong>Before you paste:</strong> Use public, hypothetical, or appropriately de-identified information only, unless your firm has approved your AI environment for the data involved.</p></div></section>
   <PracticalLab key={role} role={role}/>
   <section id="resources" className="section resources"><div className="shell resource-layout"><div><div className="kicker">TAKE IT WITH YOU</div><h2>Free resources to share with your team.</h2><p>Simple PDFs you can keep, print, or use in a discussion about practice efficiency.</p></div><div className="resource-cards"><a className="resource-card" href={role==='advisor'?'/guides/advisor-ai-one-page.pdf':'/guides/wholesaler-ai-one-page.pdf'} download><div className="pdf-icon">PDF</div><div><span>QUICK START · 1 PAGE</span><h3>{role==='advisor'?'Advisor AI Blueprint':'Wholesaler AI Blueprint'}</h3><p>{role==='advisor'?'The high-level framework for meeting prep, follow-up, communication, and efficiency.':'The high-level framework for territory intelligence, meeting prep, advisor campaigns, and execution.'}</p></div><span className="resource-arrow">↓</span></a><a className="resource-card" href="/guides/ai-full-blueprint.pdf" download><div className="pdf-icon">PDF</div><div><span>DEEPER DIVE · 9 PAGES</span><h3>Full AI Revenue Operating System</h3><p>Extended workflows for advisors and wholesalers, with examples and compliance reminders.</p></div><span className="resource-arrow">↓</span></a></div></div></section>
   <section id="safety" className="section safety"><div className="shell safety-layout"><div><div className="kicker">THE ESSENTIAL GUARDRAILS</div><h2>Use AI confidently.<br/>Keep judgment human.</h2><p>Good processes matter more than clever prompts. Follow your firm’s rules before connecting AI to real business information or sending content externally.</p></div><div className="safety-list">{[['Protect information','Never paste nonpublic client data into a tool that your firm has not authorized for that use.'],['Verify every output','AI can invent facts and sources. Check data, dates, calculations, and product claims.'],['Review communications','Follow firm approval, marketing, recordkeeping, and supervision requirements.'],['Keep advice human','Do not rely on AI to independently determine suitability, make recommendations, or promise results.']].map(([h,t],i)=><div className="safety-item" key={h}><span>0{i+1}</span><div><h3>{h}</h3><p>{t}</p></div></div>)}</div></div></section>
   <section className="section faq-section"><div className="shell faq-layout"><div><div className="kicker">FREQUENTLY ASKED QUESTIONS</div><h2>Questions? Start here.</h2><p>For your firm’s specific rules, always consult the appropriate internal compliance and technology teams.</p></div><div className="faq-list">{faqs.map(([q,a],i)=><div className="faq-item" key={q}><button onClick={()=>setExpanded(expanded===i?-1:i)} aria-expanded={expanded===i}>{q}<span>{expanded===i?'−':'+'}</span></button>{expanded===i&&<p>{a}</p>}</div>)}</div></div></section>
   <section className="closing"><div className="shell closing-inner"><div className="kicker light">READY TO START?</div><h2>Your next hour can be simpler.</h2><p>Pick one repetitive task. Try one prompt. Review the result. That’s how a better workflow begins.</p><a className="btn btn-light" href="#prompt-library">Explore the prompt library <span>→</span></a></div></section>
  </main>
  <footer><div className="shell footer-top"><a className="brand footer-brand" href="#top"><span className="brand-mark">A<span>✦</span></span><span><strong>AI Practice Blueprint</strong><small>Simple AI. Stronger relationships.</small></span></a><div className="footer-links"><a href="#popular-questions">Common questions</a><a href="#how">Blueprint</a><a href="#prompt-library">Prompts</a><a href="#resources">Downloads</a><a href="#safety">Guardrails</a></div></div><div className="shell footer-bottom"><span>© {new Date().getFullYear()} AI Practice Blueprint. Educational resource for financial professionals.</span><span>Independent educational material. Not investment, legal, or compliance advice. No affiliation or firm approval is implied.</span></div></footer>
 </div>
}
